// generated by tools/map_bond.py from src/bond/cheats.cpp
#define AUF_LANG_FRE
// Cheats (issue #5): the game kept Quake III's console. 0x14DF00 (cdecl: the line) runs a command line at once, on the game's
// thread: god and g_unlimited_ammo here (give takes neither "all" nor a pickup's name: no weapons cheat yet). Each frame (0x138760, src/bond/framerate.cpp) the settings are made so.
#include "bond/addr.h"
#include <chrono>
#include <cstdlib>
#include <cstring>
#include <string>

#include "common/auf.h"
#include "core/log.h"
#include "kernel/kernel.h"
#include "xdk/hle.h"

X86_EXTERN_FUNC(sub_0014DE10);

namespace auf {
// the line on the guest's stack below its esp, its address the argument, a return address the callee's ret takes
void RunCommand(X86Context& ctx, uint8_t* base, const char* line) {
    const uint32_t esp = ctx.esp;
    const size_t n = std::strlen(line) + 1;
    const uint32_t text = (esp - 0x200 - uint32_t(n)) & ~3u;
    std::memcpy(&kernel::G<uint8_t>(text), line, n);
    ctx.esp = text - 4;
    X86_PUSH32(text);
    X86_PUSH32(A(0x138760));
    sub_0014DE10(ctx, base);
    ctx.esp = esp;
    LOG_FIRST(16, "auf: console \"%s\"", line);
}

void CheatsFrame(X86Context& ctx, uint8_t* base) {
    // the settings made so in play, a command each when one changes, god again every two seconds (a new mission is a new
    // player). Commands marked a cheat run while the "cheats" cvar's integer (+0x20) is set (0x710A2).
    static int frames = 0;
    static bool god = false, ammo = false;
    static auto next = std::chrono::steady_clock::now();
    frames++;
    if (MenuUp() || PlayerFree() == false) return;
    const bool any = cheat_god || cheat_ammo;
    const uint32_t cvar = kernel::R32(A(0x328C7C));
    if (!cvar) return;
    if (any) {
        kernel::W32(cvar + 0x20, 1);
        kernel::G<float>(cvar + 0x1C) = 1;
    }
    const auto now = std::chrono::steady_clock::now();
    const bool again = now >= next;
    if (again) next = now + std::chrono::seconds(2);
    if (cheat_god != god || (cheat_god && again)) {
        RunCommand(ctx, base, cheat_god ? "god 1" : "god 0");
        god = cheat_god;
    }
    if (cheat_ammo != ammo) {
        RunCommand(ctx, base, cheat_ammo ? "set g_unlimited_ammo 1" : "set g_unlimited_ammo 0");
        ammo = cheat_ammo;
    }
    if (!any && god == false && ammo == false) kernel::W32(cvar + 0x20, 0), kernel::G<float>(cvar + 0x1C) = 0;
    // AUF_CHEAT_TEST=frame:line;line runs lines once (headless)
    static const char* test = std::getenv("AUF_CHEAT_TEST");
    if (!test || frames < std::atoi(test)) return;
    std::string lines = std::strchr(test, ':') ? std::strchr(test, ':') + 1 : "";
    test = nullptr;
    for (size_t at = 0; at < lines.size();) {
        size_t end = lines.find(';', at);
        if (end == std::string::npos) end = lines.size();
        RunCommand(ctx, base, lines.substr(at, end - at).c_str());
        at = end + 1;
    }
}
}  // namespace auf
